        "id": "SG-001",
        "name": "CLZ Opcode Definition",
        "description": "Defines the new CLZ (Count Leading Zeros) opcode (0x1e) for the EVM. The opcode pops one 256-bit value from the stack and pushes the count of leading zero bits. For a zero input, the result is 256.",
        "invariants": [
          {
            "id": "INV-001",
            "text": "CLZ(x) must return a value in the range [0, 256] inclusive for any 256-bit input x."
          },
          {
            "id": "INV-002",
            "text": "CLZ(0) must always equal 256."
          },
          {
            "id": "INV-003",
            "text": "For any nonzero x, CLZ(x) must equal the index of the most significant set bit counted from the top (bit 255), i.e. CLZ(x) = 255 - floor(log2(x))."
          },
          {
            "id": "INV-004",
            "text": "CLZ is a pure (stateless) function: the result depends only on the input value and not on any EVM state."
          }
        ],
        "pre_conditions": [
          {
            "id": "PRE-001",
            "text": "The EVM stack must contain at least one element before executing CLZ."
          }
        ],
        "post_conditions": [
          {
            "id": "POST-001",
            "text": "After execution, the stack depth is unchanged (one element popped, one pushed)."
          },
          {
            "id": "POST-002",
            "text": "The pushed value is a 256-bit word representing the count of leading zero bits of the popped value."
          }
        ],
        "functions": [
          {
            "id": "FN-001",
            "signature": "CLZ(x: uint256) -> uint256",
            "description": "Pops one 256-bit value x from the stack. Pushes the number of leading zero bits in x. If x is zero, pushes 256.",
            "opcode": "0x1e",
            "stack_input": 1,
            "stack_output": 1
          }
        ],
        "state_variables": [],
        "data_structures": []
      },
      {
        "id": "SG-002",
        "name": "Stack Behavior",
        "description": "Defines the stack input/output behavior of the CLZ opcode. CLZ pops exactly one value and pushes exactly one value, making it a unary stack operation with no net stack depth change.",
        "invariants": [
          {
            "id": "INV-005",
            "text": "CLZ consumes exactly 1 stack element and produces exactly 1 stack element."
          },
          {
            "id": "INV-006",
            "text": "Net stack depth change is zero: delta = 0 (pops 1, pushes 1)."
          }
        ],
        "pre_conditions": [
          {
            "id": "PRE-002",
            "text": "Stack must have depth >= 1 before CLZ execution; otherwise a stack underflow error occurs."
          }
        ],
        "post_conditions": [
          {
            "id": "POST-003",
            "text": "The top of stack contains the CLZ result; all other stack elements are unchanged."
          }
        ],
        "functions": [],
        "state_variables": [],
        "data_structures": [
