                "type": "uint256",
                "description": "The 256-bit value whose leading zeros are to be counted (popped from stack)."
              },
              {
                "name": "output",
                "type": "uint256",
                "description": "The count of leading zero bits, range [0, 256] (pushed to stack)."
              }
            ]
          }
        ]
      },
      {
        "id": "SG-003",
        "name": "Gas Cost Model",
        "description": "Defines the gas cost of the CLZ opcode at 5 gas units, matching the MUL opcode. This pricing is raised from the baseline of 3 gas (used by ADD) to avoid under-pricing DoS risk, even though benchmarks show CLZ uses approximately the same compute cycles as ADD.",
        "invariants": [
          {
            "id": "INV-007",
            "text": "The gas cost of CLZ is a fixed constant of 5 gas units, independent of input value."
          },
          {
            "id": "INV-008",
            "text": "CLZ gas cost matches MUL gas cost (both 5 gas)."
          }
        ],
        "pre_conditions": [],
        "post_conditions": [
          {
            "id": "POST-004",
            "text": "Exactly 5 gas is deducted from the available gas upon CLZ execution."
          }
        ],
        "functions": [],
        "state_variables": [
          {
            "id": "SV-001",
            "name": "GAS_CLZ",
            "type": "uint256",
            "value": "5",
            "description": "Fixed gas cost for the CLZ opcode, set equal to MUL gas cost."
          }
        ],
        "data_structures": []
      },
      {
        "id": "SG-004",
        "name": "Zero Input Special Case",
        "description": "Defines the behavior of CLZ when the input is zero. The specification mandates CLZ(0) = 256, which is the smallest number after 255 and represents the total bit width of the EVM word. This design allows efficient byte scanning via '256 >> 3 = 32' and minimal bytecode for comparisons.",
        "invariants": [
          {
            "id": "INV-009",
            "text": "CLZ(0) = 256 (all 256 bits are zero, so the leading zero count equals the full word width)."
          },
          {
            "id": "INV-010",
            "text": "For byte scanning of a zero word, CLZ(0) >> 3 must equal 32 (the number of bytes to skip)."
          }
        ],
        "pre_conditions": [],
        "post_conditions": [],
        "functions": [],
        "state_variables": [],
        "data_structures": []
      },
      {
        "id": "SG-005",
        "name": "CLZ vs CTZ Design Rationale",
        "description": "Documents the rationale for choosing CLZ over CTZ (Count Trailing Zeros). CLZ is strictly more powerful: CTZ can be derived from CLZ via the identity CTZ(x) = CLZ(x & -x) (isolate the least significant bit, then count leading zeros), but CLZ cannot be derived from CTZ.",
        "invariants": [
