        "id": "SG-009",
        "name": "Use Cases and Applications",
        "description": "Documents the primary use cases that motivate the CLZ opcode. CLZ is a fundamental building block for efficient math operations, byte operations, compression, and data structures in the EVM.",
        "invariants": [],
        "pre_conditions": [],
        "post_conditions": [],
        "functions": [],
        "state_variables": [],
        "data_structures": [],
        "use_cases": [
