            "id": "UC-001",
            "name": "lnWad",
            "description": "Natural logarithm in fixed-point WAD arithmetic. CLZ is used to efficiently determine the magnitude of the input."
          },
          {
            "id": "UC-002",
            "name": "powWad",
            "description": "Exponentiation in fixed-point WAD arithmetic."
          },
          {
            "id": "UC-003",
            "name": "lambertW0Wad",
